/**
 * Applies the SQL migrations in apps/web/drizzle (generated by `pnpm db:generate`, committed) as the database
 * OWNER: DIRECT_DATABASE_URL when onboarding provides one, else DATABASE_URL. Never APP_DATABASE_URL (cv_app has no
 * DDL rights by design).
 *
 * Entry points: `pnpm db:migrate` locally (scripts/migrate.ts), and in the image the PreSync Job runs the server
 * entry with CV_MIGRATE_AND_EXIT=true (instrumentation.ts), so the one image is the only artefact. One Job runs at a
 * time (Argo hook), so there is no advisory lock: a session-level lock would leak through PgBouncer's transaction
 * pooling.
 */
import { join } from 'node:path';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';

export async function runMigrations(url: string, migrationsFolder: string): Promise<void> {
  const sql = postgres(url, { prepare: false, max: 1, connect_timeout: 10, onnotice: () => undefined });
  try {
    await migrate(drizzle(sql), { migrationsFolder });
  } finally {
    await sql.end({ timeout: 5 });
  }
}

/** The committed migrations, relative to the app directory (the standalone server chdirs there). */
export function defaultMigrationsFolder(appDir: string = process.cwd()): string {
  return join(appDir, 'drizzle');
}
